/** Metadata only. The owning consumers retain parsing, validation and write authority. */
const RUNTIME_INPUT_CONTRACT_VERSION = "einzbern.runtime-input-contract.v1" as const;

export type RuntimeInputClassification = "startup-override" | "host-context" | "internal-transient" | "browser-preference" | "lifecycle-input" | "managed-integration" | "test-only";
export type RuntimeInputKind = "environment" | "portal-argument" | "cli-argument" | "installer-argument" | "browser-storage" | "host-file";
export interface RuntimeCommandFlag {
  readonly name: string;
  readonly required: boolean;
  readonly valueKind: string;
  readonly valueShape?: string;
  readonly nullSentinel?: string;
  readonly deprecatedAliases?: readonly string[];
}
export interface RuntimeCommandCatalogEntry {
  readonly name: string;
  readonly availability: string;
  readonly mutates: boolean;
  readonly authorityBearing?: boolean;
  readonly flags: readonly RuntimeCommandFlag[];
}
export interface RuntimeInputEntry {
  readonly key: string;
  readonly kind: RuntimeInputKind;
  readonly name: string;
  readonly classification: RuntimeInputClassification;
  readonly visibility: "public" | "integration" | "internal" | "test-only";
  readonly semanticType: "path" | "string" | "enum" | "integer" | "boolean" | "json" | "instant" | "digest" | "version" | "managed-record";
  readonly transport: "environment-string" | "argv-string" | "localStorage-string" | "host-file";
  readonly validation: string;
  /** A literal fallback only; null means absent, required or contextual as defaultDescription explains. */
  readonly defaultValue: string | number | boolean | null;
  readonly defaultDescription: string;
  /** Highest priority first, specific to this consumer rather than a global configuration chain. */
  readonly precedence: readonly string[];
  readonly owner: string;
  readonly scope: string;
  readonly source: string;
  readonly persistence: "process" | "invocation" | "browser" | "managed-device-file";
  readonly sensitivity: "ordinary" | "local-path" | "actor-identifier" | "execution-target" | "transient-token" | "context-may-contain-private-data";
  readonly pathBase: string | null;
  readonly sharing: string;
  readonly export: string;
  readonly effect: string;
  readonly restart: string;
  readonly consumer: readonly string[];
  readonly editing: string;
  readonly consumption: "wired" | "helper-only" | "test-only";
  readonly allowedValues?: readonly string[];
  readonly min?: number;
  readonly max?: number;
  readonly command?: string;
  readonly catalogReference?: string;
  /** Supplied from COMMAND_CATALOG, never a second parser or a guessed flag declaration. */
  readonly flag?: RuntimeCommandFlag;
}

type EntryInput = Pick<RuntimeInputEntry, "key" | "kind" | "name" | "semanticType" | "validation" | "defaultDescription" | "precedence" | "scope" | "consumer" | "effect"> & Partial<RuntimeInputEntry>;
function entry(input: EntryInput): RuntimeInputEntry {
  return Object.freeze({
    classification: "startup-override",
    visibility: "public",
    transport: "environment-string",
    defaultValue: null,
    owner: "device-user",
    source: input.kind === "environment" ? "process environment" : "explicit invocation",
    persistence: "process",
    sensitivity: "ordinary",
    pathBase: null,
    sharing: "device-local; never a shared library declaration",
    export: "not exported to shared AGENTS or config/project.json",
    restart: "next invocation; restart a long-running process to change its startup input",
    editing: "dedicated invocation only; not a generic settings-editor field",
    consumption: "wired",
    ...input,
    precedence: Object.freeze([...input.precedence]),
    consumer: Object.freeze([...input.consumer]),
    ...(input.allowedValues === undefined ? {} : { allowedValues: Object.freeze([...input.allowedValues]) }),
  });
}

