// Bounded invocation metadata consumes the caller's real package catalog; it never
// creates a second parser, imports the CLI into core or invents operational defaults.
const DOT_COMMANDS = new Set(["execution-codex-peer-record", "execution-codex-peer-evidence", "config-backup-plan", "config-backup-create", "config-backup-verify", "config-backup-list", "config-backup-resume", "config-backup-retire", "config-restore-plan", "config-restore-apply", "execution-native-prepare", "execution-native-record", "execution-native-evidence", "shared-submit-plan", "shared-submit-evidence", "shared-submit-advisory-read", "shared-submit-advisory-write"]);
function dotInvocationEntries(commands: readonly RuntimeCommandCatalogEntry[]): RuntimeInputEntry[] {
  return commands.filter(command => DOT_COMMANDS.has(command.name)).flatMap(command => command.flags.map(flag => {
    const backup = command.name.startsWith("config-");
    const peer = command.name.startsWith("execution-codex-peer-");
    const file = ["request", "output", "package", "root", "tool-contract", "arguments", "binding", "response", "from-file", "prior", "retry-from", "reconciliation", "manifest", "records", "capacity", "delivery"].includes(flag.name);
    const path = file || ["workspace", "project"].includes(flag.name);
    const fallback = flag.required ? "required; no inferred value" : flag.name === "root" ? "absent: not-scanned" : flag.name === "response" ? "absent: pending attempt, not completion" : flag.name === "timeout-ms" ? "existing local lock wait budget; not retention policy or capacity" : flag.name === "output" ? "absent: canonical CLI result only" : ["workspace", "project", "project-id"].includes(flag.name) ? "actual unambiguous registry binding only; no new identity" : "absent; no fabricated evidence, identity, approval or revision";
    return cli(command.name, flag.name, {
      semanticType: path ? "path" : flag.valueKind === "integer" ? "integer" : flag.valueKind === "instant" ? "instant" : flag.name === "approved-plan-digest" ? "digest" : "string",
      validation: `${flag.valueShape ?? flag.valueKind}. Existing strict pair parser rejects unknown/duplicate flags. ${backup && file ? "File/root paths must be absolute and normalized; create-new outputs never overwrite." : path ? "Resolved by the owning consumer; no guessed target or authority." : flag.name === "timeout-ms" ? "Nonnegative safe integer lock wait only." : "Owning typed validator remains authoritative."}`,
      defaultDescription: fallback,
      precedence: [`explicit ${command.name} --${flag.name}`, fallback],
      scope: backup ? "one explicit registered source or reserved configuration-backup root" : peer ? "one fixed Codex peer batch receipt" : "one native attempt or shared-submit advisory",
      sensitivity: file ? "context-may-contain-private-data" : path ? "local-path" : flag.name === "actor" ? "actor-identifier" : flag.name === "tool" ? "execution-target" : "ordinary",
      pathBase: path ? backup && file ? "explicit absolute path" : "process cwd for relative path; owning consumer validates" : null,
      sharing: "private local invocation; only declared normalized evidence may be shared",
      export: "not a shared setting; no raw tool arguments, tokens, local paths or backup content promoted to governed evidence",
      consumer: ["packages/cli/src/index.ts dispatchCli", backup ? "packages/cli/src/config-backup-commands.ts runConfigBackupCommand" : "packages/cli/src/native-tool-commands.ts runNativeToolCommand"],
      effect: peer ? "Recomputes fixed membership, actual native results and report delivery; retained latest prior prevents blind redispatch/resend. Recording never launches peers, sends messages or grants authorization." : backup ? "Uses explicit selection, reserved roots and exact approved policy. Backup/restore source version must come from two stable reads of the actual running package artifact; source/dist layouts and missing version binding refuse, and a request cannot supply it. Restore still requires per-key permission, unchanged plan and originals-first backup." : "Native evidence never supplies a process exit code. Unknown terminality, acceptance without readback, parallel serial-only requests and unmet independent verification cannot become completed; advisory is not a distributed lock.",
      restart: "one invocation only; no persistent target, policy, schedule or admission bypass",
    });
  }));
}

