export interface RuntimeInputContract {
  readonly schemaVersion: typeof RUNTIME_INPUT_CONTRACT_VERSION;
  readonly entries: readonly RuntimeInputEntry[];
  readonly commandCatalog: readonly RuntimeCommandCatalogEntry[];
  readonly commandCatalogAttached: boolean;
  readonly commandCatalogRole: "operational-invocation-payloads";
  readonly coverage: typeof RUNTIME_INPUT_DISCOVERY;
  readonly limits: readonly string[];
}

/** All flags remain available through the caller's existing command catalog, including flags outside this lifecycle dictionary. */
export function runtimeInputContract(commandCatalog: readonly RuntimeCommandCatalogEntry[] = []): RuntimeInputContract {
  const commands = Object.freeze(commandCatalog.map((command) => Object.freeze({ ...command, flags: Object.freeze(command.flags.map((flag) => Object.freeze({ ...flag, ...(flag.deprecatedAliases === undefined ? {} : { deprecatedAliases: Object.freeze([...flag.deprecatedAliases]) }) }))) })));
  const cliEntries = [...CLI_ENTRIES, ...dotInvocationEntries(commands)].map((row) => {
    if (commandCatalog.length === 0) return row;
    const flag = commands.find((command) => command.name === row.command)?.flags.find((candidate) => `--${candidate.name}` === row.name);
    if (flag === undefined) throw new Error(`RUNTIME_INPUT_CATALOG_MISMATCH: ${row.catalogReference}`);
    return Object.freeze({ ...row, flag });
  });
  return Object.freeze({
    schemaVersion: RUNTIME_INPUT_CONTRACT_VERSION,
    entries: Object.freeze([...ENVIRONMENT_ENTRIES, ...TEST_ENTRIES, ...BROWSER_ENTRIES, ...PORTAL_ARGUMENT_ENTRIES, ...cliEntries, ...INSTALLER_ENTRIES, ...HOST_ENTRIES]),
    commandCatalog: commands,
    commandCatalogRole: "operational-invocation-payloads",
    commandCatalogAttached: commandCatalog.length !== 0,
    coverage: RUNTIME_INPUT_DISCOVERY,
    limits: Object.freeze([
      "Metadata never reads process.env, localStorage, host files, credentials or actual runtime values; no runtime behavior or authority changes.",
      "Detailed per-field defaults cover the registered runtime/startup/browser/lifecycle entries, not every operational CLI payload. All supplied command flags retain their original catalog metadata without inferred defaults.",
      "Null defaultValue is not an empty-string default: defaultDescription distinguishes required, absent and contextual defaults. Precedence is consumer-specific.",
      "Discovery is bounded to the declared source roots and explicit entry/support files. Tests detect new literal product-owned names there; dynamic names and excluded tools need separate review.",
      "Presence of a consumer reference proves source wiring only, not real host acceptance, installation state, live quota access or user approval.",
    ]),
  });
}
